def main() -> None:
    import hashlib
    patch = zlib.decompress(base64.b85decode(PATCH_B85))
    actual = hashlib.sha256(patch).hexdigest()
    if actual != PATCH_SHA256:
        raise SystemExit(f"audit delta digest mismatch: {actual}")
    with tempfile.NamedTemporaryFile(suffix=".patch", delete=False) as stream:
        stream.write(patch)
        path = Path(stream.name)
    try:
        if subprocess.run(["git", "apply", "--check", str(path)]).returncode == 0:
            subprocess.run(["git", "apply", str(path)], check=True)
        elif subprocess.run(["git", "apply", "--reverse", "--check", str(path)]).returncode == 0:
            print("follow-up audit delta is already applied")
        else:
            raise SystemExit("follow-up audit delta neither applies nor matches the current tree")
    finally:
        path.unlink(missing_ok=True)


if __name__ == "__main__":
    main()
